head.script:
//
// ===================== SETTINGS =====================
// 1) Put YOUR GitHub username below (and repo name if different):
var BASE="https://cdn.jsdelivr.net/gh/YOUR-GITHUB-USERNAME/chefzafar-assets@main/";
// 2) Number of photos in each gallery folder (change when you add photos):
var N={"with-master-chef":12,"with-celebrities":3,"my-loving-touch":25};
// ====================================================
//

head.b:skin:
:root{--ink:#1E241F;--paper:#F7F3EA;--sand:#EAE2D3;--saf:#E57B20;--mut:#596159}
*{box-sizing:border-box;margin:0}html{scroll-behavior:smooth}
body{font-family:Manrope,system-ui,sans-serif;background:var(--paper);color:var(--ink);line-height:1.7}
h1,h2,h3{font-family:"DM Serif Display",Georgia,serif;font-weight:400;line-height:1.15}
a{color:inherit}.w{max-width:1120px;margin:auto;padding:0 20px}
.eb{font-size:11px;font-weight:800;letter-spacing:.2em;text-transform:uppercase;color:#A85A17}
.btn{display:inline-block;padding:13px 24px;border-radius:99px;background:var(--saf);color:#fff;font-weight:800;font-size:12px;letter-spacing:.12em;text-transform:uppercase;text-decoration:none;border:2px solid var(--saf)}
.btn.o{background:none;color:inherit;border-color:currentColor}
header{position:sticky;top:0;z-index:9;background:rgba(247,243,234,.94);backdrop-filter:blur(8px);border-bottom:1px solid #1e241f1a}
header .w{display:flex;justify-content:space-between;align-items:center;height:64px}
.logo img{height:54px;display:block}.hl{height:clamp(140px,18vw,210px);display:block;margin:0 0 22px -8px}.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}nav a{white-space:nowrap}
nav a{margin-left:20px;font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.1em;text-decoration:none}nav a:hover{color:var(--saf)}.mb{display:none;background:none;border:0;color:var(--ink);cursor:pointer;padding:6px;border-radius:8px}
.hero .w{display:grid;grid-template-columns:1fr 1fr;min-height:640px;gap:0}
.hero{background:var(--sand)}
.pic{position:relative;background:var(--ink) center/cover}
.pic img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:50% 0}
.txt{padding:64px 0 64px 56px;align-self:center}
.txt h1{font-size:clamp(38px,5vw,64px);margin:16px 0}.txt h1 em{color:var(--saf)}
.txt p{max-width:440px;color:var(--mut);margin-bottom:28px}.txt .btn+.btn{margin-left:10px;color:var(--ink)}
section{padding:88px 0}.sec2{background:var(--sand)}.dark{background:var(--ink);color:var(--paper)}
h2{font-size:clamp(30px,4vw,46px);margin:12px 0 20px}
.tl{display:grid;gap:22px;margin-top:40px;grid-template-columns:repeat(2,1fr)}
.tl div{background:#FFFDF8;padding:26px;border-radius:14px;border:1px solid #1e241f14}
.tl b{font-family:"DM Serif Display";color:var(--saf);font-size:26px;font-weight:400}.tl h3{font-size:22px;margin:4px 0 8px}.tl p{font-size:14px;color:var(--mut)}
blockquote{font-family:"DM Serif Display";font-size:clamp(22px,3vw,32px);margin:36px 0 0;border-left:4px solid var(--saf);padding-left:20px}
.ex{display:grid;grid-template-columns:1.3fr 1fr;gap:28px;margin-top:36px}.ex h3{font-size:24px;color:#F2C08C;margin:0 0 16px}.ex>div>div{margin-bottom:26px}.ex ul{list-style:none;padding:0}.ex li{padding:0 0 14px 18px;border-left:2px solid #E57B2066;position:relative;font-size:14px;opacity:.92}.ex li:before{content:"";position:absolute;left:-6px;top:6px;width:10px;height:10px;border-radius:50%;background:var(--saf)}.ex li b{display:block;font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:#EAA65F}.ex li span{opacity:.7}#ge{margin-top:28px;color:var(--mut)}
.vid{display:block;width:100%;aspect-ratio:1/1;object-fit:cover;border-radius:16px;background:#000}.sv{display:grid;grid-template-columns:minmax(0,480px) 1fr;gap:40px;align-items:center;margin-top:8px}#gal{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:12px;margin-top:24px}
#gal img{width:100%;aspect-ratio:1;object-fit:cover;border-radius:12px;cursor:zoom-in;background:var(--sand)}
.tabs{display:flex;flex-wrap:wrap;gap:10px;margin-top:20px}.tabs button{font:800 12px Manrope,sans-serif;letter-spacing:.1em;text-transform:uppercase;padding:11px 20px;border-radius:99px;border:2px solid var(--ink);background:none;color:var(--ink);cursor:pointer}.tabs button.on{background:var(--ink);color:var(--paper)}
#lb{position:fixed;inset:0;background:#000e;display:none;align-items:center;justify-content:center;z-index:99}#lb img{max-width:92vw;max-height:88vh;border-radius:8px}
#lb button{position:absolute;background:#ffffff26;color:#fff;border:0;width:46px;height:46px;border-radius:50%;font-size:30px;line-height:1;cursor:pointer}.lx{top:16px;right:16px}.lp{left:12px;top:50%}.ln{right:12px;top:50%}
.sv .g3{grid-template-columns:1fr;gap:18px}
.fac{background:var(--saf);color:var(--ink);padding-top:0}.fac .eb{color:var(--ink)}.fac h2{font-size:clamp(40px,7vw,84px);line-height:1}.fac h2 em{display:block;font-size:.5em;margin-top:10px}
.fac .lead{max-width:600px;font-size:18px;margin-bottom:8px}.fac .btn{background:var(--ink);border-color:var(--ink)}.fac .btn.o{background:none;color:var(--ink)}
.mq{background:var(--ink);color:var(--paper);overflow:hidden;white-space:nowrap;padding:14px 0;margin-bottom:72px}.mq div{display:inline-block;animation:mq 30s linear infinite}
.mq span{margin:0 22px;font:800 12px Manrope,sans-serif;letter-spacing:.2em;text-transform:uppercase}.mq span:after{content:"\2726";margin-left:44px;color:var(--saf)}
@keyframes mq{to{transform:translateX(-50%)}}@media(prefers-reduced-motion:reduce){.mq div{animation:none}}
.fc div{background:var(--ink);color:var(--paper);padding:28px;border-radius:16px}.fc b{font-family:"DM Serif Display",serif;font-weight:400;font-size:44px;color:var(--saf);line-height:1}.fc h3{margin:8px 0 10px;font-size:24px}.fc p{font-size:14px;opacity:.8}
.g3{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:36px}
.card{background:#FFFDF8;border-radius:16px;overflow:hidden;border:1px solid #1e241f14;display:flex;flex-direction:column}
.card img{width:100%;aspect-ratio:4/3;object-fit:cover;background:var(--sand)}
.card div{padding:22px}.card h3{font-size:24px;margin:6px 0}.card p{font-size:14px;color:var(--mut)}
.pil{background:none;border:0;padding:0}.pil b{color:var(--saf);font-size:13px;letter-spacing:.15em}
.pr{font-family:"DM Serif Display";font-size:26px;margin-top:14px}.pr del{font-size:14px;opacity:.5}
.hd{display:flex;align-items:center;gap:16px;background:var(--ink);padding:28px;border-radius:16px;margin-bottom:8px}
.hd img{height:72px;background:#FFFDF8;border-radius:6px;padding:4px}
.cta{text-align:center}.cta h2{max-width:680px;margin:12px auto 18px}.cta p{max-width:520px;margin:0 auto 28px;opacity:.7}
footer{background:#161b17;color:#F7F3EAcc;padding:40px 0;font-size:14px}footer .w{display:flex;justify-content:space-between;flex-wrap:wrap;gap:16px}

.st{display:grid;gap:28px;margin-top:36px}
.st .card{flex-direction:row}.st .card img{width:46%;aspect-ratio:auto;min-height:340px;object-fit:cover;flex-shrink:0}
.st .card img.cv{object-fit:contain;padding:24px;width:34%;min-height:0;align-self:center;background:var(--sand);height:auto;max-height:480px}.st .card div{padding:36px;align-self:center}
.st .card h3{font-size:clamp(26px,3vw,34px)}.st .card p{font-size:15px}
.bt{display:flex;flex-wrap:wrap;gap:10px}.bt.c{justify-content:center}img{max-width:100%}.txt .bt .btn+.btn{margin-left:0}
@media(max-width:1024px){.st .card div{padding:26px}}
@media(max-width:560px){#gal{grid-template-columns:repeat(2,1fr);gap:8px}.tabs button{padding:10px 14px;font-size:11px}}
@media(max-width:820px){.sv{grid-template-columns:1fr;gap:24px}.vid{max-width:520px}section{padding:56px 0}.st .card{flex-direction:column}.st .card img{width:100%;min-height:0;aspect-ratio:4/3}.st .card img.cv{width:100%;aspect-ratio:1/1;max-height:380px;height:auto}.st .card div{padding:22px;align-self:stretch}.hd{flex-direction:column;text-align:center}header .w{height:60px}.logo{flex-shrink:0}.logo img{height:46px}.pic{min-height:380px}.txt{padding:36px 0 48px}}
@media(max-width:1100px){.mb{display:flex}nav{display:none;position:absolute;top:100%;left:0;right:0;background:var(--paper);flex-direction:column;padding:8px 20px 16px;border-bottom:1px solid #1e241f1a;box-shadow:0 12px 24px #0002}nav a{margin:0;padding:14px 0;font-size:13px;border-bottom:1px solid #1e241f14}header.open nav{display:flex}}
@media(max-width:820px){.hero .w{grid-template-columns:1fr}.pic{min-height:420px}.txt{padding:40px 0}.tl,.g3,.ex{grid-template-columns:1fr}}

body.script:
//
document.querySelectorAll("[data-p]").forEach(function(e){e.poster=BASE+e.getAttribute("data-p")});
document.querySelectorAll("[data-a]").forEach(function(e){e.src=BASE+e.getAttribute("data-a")});

var C=[["with-master-chef","With Master Chef"],["with-celebrities","With Celebrities"],["my-loving-touch","My Loving Touch"]],P={"with-master-chef":"master-","with-celebrities":"celeb-","my-loving-touch":"touch-"},L={},cur=0,li=0;
var g=document.getElementById("gal"),tb=document.getElementById("tabs"),lb=document.getElementById("lb"),li_=lb.querySelector("img");
function src(j){return BASE+P[C[cur][0]]+L[C[cur][0]][j]}
function show(i){cur=i;g.innerHTML="";[].forEach.call(tb.children,function(b,k){b.className=k==i?"on":""});
 L[C[i][0]].forEach(function(f,j){var m=new Image();m.src=src(j);m.alt=C[i][1]+" "+(j+1);m.loading="lazy";m.onclick=function(){open_(j)};g.appendChild(m)})}
function open_(j){var n=L[C[cur][0]].length;li=(j+n)%n;li_.src=src(li);lb.style.display="flex"}
function init(d){C.forEach(function(c,i){L[c[0]]=d[c[0]]||[];var b=document.createElement("button");b.textContent=c[1]+" ("+L[c[0]].length+")";b.onclick=function(){show(i)};tb.appendChild(b)});show(0)}
function fb(){var d={};for(var k in N){d[k]=[];for(var i=1;i<=N[k];i++)d[k].push(i+".jpg")}return d}
init(fb());
document.getElementById("lp").onclick=function(e){e.stopPropagation();open_(li-1)};document.getElementById("ln").onclick=function(e){e.stopPropagation();open_(li+1)};
document.getElementById("lx").onclick=function(){lb.style.display="none"};lb.onclick=function(e){if(e.target==lb)lb.style.display="none"};
document.onkeydown=function(e){if(lb.style.display!="flex")return;if(e.key=="Escape")lb.style.display="none";if(e.key=="ArrowLeft")open_(li-1);if(e.key=="ArrowRight")open_(li+1)};
var hd=document.querySelector("header"),mb=document.getElementById("mb");
function tg(o){hd.classList.toggle("open",o);mb.setAttribute("aria-expanded",o);document.getElementById("mp").setAttribute("d",o?"M6 6l12 12M18 6L6 18":"M4 7h16M4 12h16M4 17h16")}
mb.onclick=function(){tg(!hd.classList.contains("open"))};document.querySelectorAll("nav a").forEach(function(a){a.onclick=function(){tg(false)}});

//
